-- Chạy sau migration trong Supabase SQL Editor. Thay demo_owner bằng UUID của user đã đăng ký.
do $$ begin if not exists(select 1 from auth.users limit 1) then raise notice 'Đăng ký một user trước khi chạy seed'; return; end if; end $$;
with owner as (select id from auth.users order by created_at limit 1), u as (insert into public.users(id,display_name) select id,'Nguyễn Tuấn' from owner on conflict(id) do update set display_name=excluded.display_name returning id), t as (insert into public.teams(name,abbreviation,primary_color,created_by) select 'HVC Volleyball Club','HVC','#7056F5',id from u returning id,created_by), tm as (insert into public.team_members(team_id,user_id,role) select id,created_by,'owner' from t), s as (insert into public.seasons(team_id,name,starts_on,ends_on,is_active) select id,'Mùa giải 2026','2026-01-01','2026-12-31',true from t returning id,team_id)
insert into public.players(team_id,full_name,jersey_number,position) select s.team_id,p.name,p.no,p.pos::public.player_position from s cross join (values ('Thịnh',17,'setter'),('Minh',10,'outside_hitter'),('Nam',7,'middle_blocker'),('Hoàng',5,'opposite'),('Long',3,'libero'),('Đức',11,'outside_hitter')) p(name,no,pos);

with s as (select id,team_id from seasons where name='Mùa giải 2026' limit 1), games(d,opp,hs,ascore) as (values ('2026-07-13'::date,'Lotus VC',1,3),('2026-07-20','Phoenix Team',3,1),('2026-07-27','Skyline Club',2,3),('2026-08-03','Bắc Ninh United',3,0),('2026-08-10','Thunder VC',3,1)) insert into matches(team_id,season_id,match_code,played_at,competition,venue,home_team_name,away_team_name,best_of,home_sets,away_sets,status) select s.team_id,s.id,'HVC-'||to_char(d,'YYYYMMDD'),d+'19:00'::time,'Hanoi Open','HVC Arena','HVC Volleyball Club',opp,5,hs,ascore,'completed' from s cross join games;

with setter as (select id from players where full_name='Thịnh' limit 1), lines(code,t,p,pl,b,e,a) as (values ('HVC-20260713',74,41,18,8,4,22),('HVC-20260720',80,49,18,6,2,27),('HVC-20260727',91,53,20,9,3,30),('HVC-20260803',68,43,15,5,1,25),('HVC-20260810',82,52,19,5,3,28)) insert into setter_match_stats(match_id,player_id,total_touches,perfect_sets,playable_sets,bad_sets,set_errors,assists) select m.id,setter.id,t,p,pl,b,e,a from lines join matches m on m.match_code=code cross join setter;
